# Hand-written Great Expectations suites, one per dataset, used by the
# greatExpectations detector when EXPECTATION_TIER=hand_written (the default).
# The other two tiers, dirty_profiled and clean_profiled, are generated by
# rein/auxiliaries/expectations_profiler.py and need no entry here.
#
# Add a dataset as DATASET_EXPECTATIONS['<dataset>']['hand_written'] = [...],
# one dict per rule: the column, the Great Expectations method name and its
# kwargs. beers below is a worked example.
#
# Note: the benchmark reads every value as a string, so number ranges are
# written as regexes (expect_column_values_to_be_between does not work here).


DATASET_EXPECTATIONS = {
    'beers': {
        'hand_written': [

            {'column': 'ounces', 'expectation': 'expect_column_values_to_match_regex',
            'kwargs': {'regex': r'^\d+(\.\d+)?$'}},

            {'column': 'abv', 'expectation': 'expect_column_values_to_match_regex',
            'kwargs': {'regex': r'^\d+(\.\d+)?$'}},

            {'column': 'brewery_id', 'expectation': 'expect_column_values_to_match_regex',
            'kwargs': {'regex': r'^\d+$'}},

            {'column': 'state', 'expectation': 'expect_column_values_to_match_regex',
            'kwargs': {'regex': r'^[A-Z]{2}$'}},

            {'column': 'ibu', 'expectation': 'expect_column_values_to_match_regex',
            'kwargs': {'regex': r'^(\d+(\.\d+)?)?$'}},

            {'column': 'id', 'expectation': 'expect_column_values_to_be_unique',
            'kwargs': {}},

            {'column': 'style', 'expectation': 'expect_column_values_to_match_regex',
            'kwargs': {'regex': r'.+'}},

            {'column': 'city', 'expectation': 'expect_column_values_to_not_match_regex',
            'kwargs': {'regex': r' [A-Z]{2}$'}},

        ]
    },

}


# Suites kept outside the repository: if rein/auxiliaries/expectations_dictionary_local.py
# exists and defines its own DATASET_EXPECTATIONS, its datasets are added here and
# override any entry of the same name above.
try:
    from rein.auxiliaries.expectations_dictionary_local import DATASET_EXPECTATIONS as _local_expectations
    DATASET_EXPECTATIONS.update(_local_expectations)
except ImportError:
    pass
